import io,gzip,base64,zipfile
import pandas as pd
import streamlit as st
st.set_page_config(page_title="V6.14 Pair FIX",page_icon="🎯",layout="wide")
st.title("🎯 V6.14 — GERÇEK PAIR İSABETİ")
DATA=""""""
@st.cache_data
def load():
    return pd.read_csv(io.BytesIO(gzip.decompress(base64.b64decode(DATA))))
p=load()
req=['draw_no', 'date', 'time', 'pair', 'H3_state', 'H2_state', 'H1_state', 'target_full11']
miss=[c for c in req if c not in p.columns]
if miss:
    st.error("Eksik sütun: "+", ".join(miss)); st.stop()

weights={"11":4.0,"01":3.0,"10":3.0,"00":1.0}
p["pre_score"]=p["H1_state"].astype(str).map(weights).fillna(0)
# H3/H2 persistence, all PRE-H
p["pre_score"] += p["H2_state"].astype(str).map(weights).fillna(0)*0.5
p["pre_score"] += p["H3_state"].astype(str).map(weights).fillna(0)*0.25
p["actual_hit"]=pd.to_numeric(p["target_full11"],errors="coerce").fillna(0).astype(int)

rows=[]; det=[]
for d,q in p.groupby("draw_no"):
    q=q.sort_values(["pre_score","pair"],ascending=[False,True]).drop_duplicates("pair")
    for k in [1,2,3,4,5]:
        s=q.head(k); h=int(s.actual_hit.sum())
        rows.append({"draw_no":int(d),"K":k,"predicted":len(s),"hits":h,"at_least_one":int(h>0)})
    for rank,(_,r) in enumerate(q.head(5).iterrows(),1):
        det.append({"draw_no":int(d),"date":r["date"],"time":r["time"],"rank":rank,"pair":r["pair"],
                    "H3":r["H3_state"],"H2":r["H2_state"],"H1":r["H1_state"],
                    "pre_score":r["pre_score"],"hit":int(r["actual_hit"])})
res=pd.DataFrame(rows); detail=pd.DataFrame(det)
summary=res.groupby("K").agg(draws=("draw_no","count"),predicted=("predicted","sum"),hits=("hits","sum"),
draws_with_hit=("at_least_one","sum")).reset_index()
summary["pair_precision"]=summary["hits"]/summary["predicted"]
summary["draw_hit_rate"]=summary["draws_with_hit"]/summary["draws"]
st.dataframe(summary,use_container_width=True,hide_index=True)
st.dataframe(detail,use_container_width=True,hide_index=True)
bio=io.BytesIO()
with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
 z.writestr("01_SUMMARY.csv",summary.to_csv(index=False).encode("utf-8-sig"))
 z.writestr("02_DETAIL.csv",detail.to_csv(index=False).encode("utf-8-sig"))
st.download_button("⬇️ SONUÇ ZIP",bio.getvalue(),"HIZLI_ON_V6_14_PAIR_RESULTS.zip","application/zip",use_container_width=True)
